pub struct ProgressBar {
    progress: i64,
    total: i64,
    width: usize,
    precision: usize,
}

impl ProgressBar {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: i64) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: i64) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn set_precision(&mut self, precision: usize) {
        self.precision = precision;
    }

    pub fn str(&self) -> String {
        self.render_at(self.width)
    }

    pub(crate) fn render_at(&self, width: usize) -> String {
        let fraction = if self.total > 0 {
            self.progress as f64 / self.total as f64
        } else {
            0.0
        };
        let filled = ((width as f64) * fraction).floor() as usize;
        let filled = filled.min(width);
        let mut bar = String::with_capacity(width + 2);
        bar.push('[');
        for _ in 0..filled {
            bar.push('=');
        }
        if filled < width {
            bar.push('>');
            for _ in 0..(width - filled - 1) {
                bar.push(' ');
            }
        }
        bar.push(']');
        format!(
            "{} {:.*}%",
            bar,
            self.precision,
            fraction as f32 * 100.0
        )
    }
}

impl Default for ProgressBar {
    fn default() -> Self {
        ProgressBar {
            progress: 0,
            total: 100,
            width: 40,
            precision: 1,
        }
    }
}

