use crate::progress_bar::ProgressBar;

const MULTI_BAR_WIDTH: usize = 50;

#[derive(Default)]
pub struct MultiProgress {
    bars: Vec<ProgressBar>,
}

impl MultiProgress {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_bar(&mut self, bar: ProgressBar) {
        self.bars.push(bar);
    }

    pub fn str(&self) -> String {
        self.bars
            .iter()
            .enumerate()
            .map(|(i, b)| format!("Bar {}: {}", i + 1, b.render_at(MULTI_BAR_WIDTH)))
            .collect::<Vec<_>>()
            .join("\n")
    }
}

