const FRAMES: [&str; 8] = ["⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"];

pub struct CyclicProgress {
    cycle: u64,
    steps: u64,
}

impl CyclicProgress {
    pub fn new(cycle: u64) -> Self {
        CyclicProgress { cycle, steps: 0 }
    }

    pub fn next(&mut self) {
        self.steps += 1;
    }

    pub fn str(&self) -> String {
        let frame = FRAMES[(self.steps as usize) % FRAMES.len()];
        let pct = if self.cycle > 0 {
            self.steps as f32 / self.cycle as f32 * 100.0
        } else {
            0.0
        };
        format!("{} {:.1}%", frame, pct)
    }
}

