use indicators::{
    Counter, CyclicProgress, Format, MultiProgress, Percentage, ProgressBar, ProgressBuilder,
    ProgressDisplay, ProgressTracker, TaskProgress,
};

fn main() {
    // arg parsing (mirrors C++ argc/argv, unused)
    let args: Vec<String> = std::env::args().collect();
    let _argc = args.len();

    // 测试所有API的组合
    let mut bar = ProgressBar::new();
    bar.set_progress(45);
    bar.set_total(90);
    bar.set_width(40);
    println!("{}", bar.str());
    println!("{}", bar.str()); // mirrors C++ operator()

    let pct1 = Percentage::new(0.45f32, 1);
    let pct2 = Percentage::new(0.67f32, 2);
    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", String::from(pct1)); // static_cast<std::string>(pct1)

    let cnt = Counter::new(45, 90);
    println!("{}", cnt.str());
    println!("{}", String::from(cnt));

    let builder = ProgressBuilder::new();
    println!("{}", builder.set_progress(45).set_total(90).build());

    let mut tracker = ProgressTracker::new();
    tracker.add_stage("A").add_stage("B").add_stage("C");
    tracker.set_progress(1);
    tracker.set_total(3);
    println!("{}", tracker.get_progress());
    println!("{}", tracker.get_percentage());

    println!("{}", Format::percentage(0.33f32));
    println!("{}", Format::progress(33, 100));
    println!("{}", Format::bar(33, 100, 25));

    let mut multi = MultiProgress::new();
    let mut b1 = ProgressBar::new();
    let mut b2 = ProgressBar::new();
    b1.set_progress(30);
    b1.set_total(100);
    b2.set_progress(60);
    b2.set_total(100);
    multi.add_bar(b1);
    multi.add_bar(b2);
    println!("{}", multi.str());

    let mut display = ProgressDisplay::new(100);
    display.update(50);
    println!("{}", display.display());
    display.increment(25);
    println!("{}", display.display());

    let mut cyclic = CyclicProgress::new(10);
    cyclic.next();
    cyclic.next();
    println!("{}", cyclic.str());

    let mut task = TaskProgress::new("Test", 10);
    task.complete(3);
    println!("{}", task.status());

    // 测试不同精度的百分比
    for i in 1..=5 {
        println!("{}", Format::percentage_with_precision(0.12345f32, i));
    }

    // 测试不同宽度的进度条
    let mut i = 10;
    while i <= 50 {
        println!("{}", Format::bar(50, 100, i));
        i += 10;
    }

    // 测试计数器数组
    let mut counters = [Counter::default(), Counter::default(), Counter::default()];
    for i in 0..3 {
        counters[i].set_current((i as i64 + 1) * 25);
        counters[i].set_total(100);
        println!("{}", counters[i].str());
    }

    // 测试百分比数组
    let percentages = [
        Percentage::new(0.25f32, 1),
        Percentage::new(0.5f32, 2),
        Percentage::new(0.75f32, 3),
    ];

    for p in percentages.iter() {
        println!("{}", p.str());
    }
}

